#include <cstdio>
using namespace std;

const int mod = 100000;
int dp[2][2001][3001];

int main() {
    int n, m, s;
    while (true) {
        scanf("%d %d %d", &n, &m, &s);
        if (n == 0) break;

        int n2 = n * n;
        for (int i = 0; i < n2; i++) {
            for (int j = 1; j <= m; j++) {
                for (int k = 1; k <= s; k++) {
                    if (i == 1) {
                        dp[1][j][k] = (j < k) ? 0 : 1;
                    }
                    dp[(i + 1) & 1][j][k] = dp[(i + 1) & 1][j - 1][k];

                    if (k - j >= 0) {
                        dp[(i + 1) & 1][j][k] += dp[i & 1][j - 1][k - j];
                    }
                    dp[(i + 1) & 1][j][k] %= mod;
                }
            }
        }
        printf("%d\n", dp[n2 & 1][m][s]);
    }
    return 0;
}

